  async function sendPushToMembers(coProId, title, body, data) {
    const db2 = getAdminDb();
    if (!db2) return;
    const membersSnap = await db2.collection("copros").doc(coProId).collection("members").get();
    const uids = membersSnap.docs.map((d) => d.id);
    if (uids.length === 0) return;
    const tokens = [];
    await Promise.all(
      uids.map(async (uid) => {
        const userDoc = await db2.collection("users").doc(uid).get();
        const token2 = userDoc.data()?.pushToken;
        if (token2 && typeof token2 === "string" && token2.startsWith("ExponentPushToken")) {
          tokens.push(token2);
        }
      })
    );
    if (tokens.length === 0) return;
    const chunks = [];
    for (let i2 = 0; i2 < tokens.length; i2 += 100) chunks.push(tokens.slice(i2, i2 + 100));
    await Promise.all(
      chunks.map(
        (chunk) => fetch("https://exp.host/--/api/v2/push/send", {
          method: "POST",
          headers: { "Content-Type": "application/json", Accept: "application/json" },
          body: JSON.stringify(
            chunk.map((to3) => ({ to: to3, title, body, data: data ?? {}, sound: "notification.wav" }))
          )
        }).catch((e3) => console.warn("[push] chunk failed:", e3))
      )
    );
  }
